  React.useEffect(() => {
    const el = scrollWrapperRef.current;

    if (!el) return;

    const updateOverflowPosition = () => {
      const { scrollLeft, scrollWidth, clientWidth } = el;

      // If no horizontal overflow, reset position
      if (scrollWidth <= clientWidth) {
        setOverflowPosition(null);
        return;
