      const atStart = scrollLeft === 0;
      const atEnd = Math.ceil(scrollLeft + clientWidth) >= scrollWidth;

      let position: 'left' | 'right' | 'center';
      if (atStart) {
        position = 'left';
      } else if (atEnd) {
        position = 'right';
      } else {
        position = 'center';
