  const addFilter = (options: {
    fieldName: FQ.FieldName,
    value: Primitive | Array<Primitive>,
    selectedOperator?: undefined | null | FQ.Operator,
    selectedSubOperator?: undefined | null | FQ.Operator,
    key?: undefined | string,
