    <TooltipProvider compact tooltip={typeof tooltip !== 'undefined' ? tooltip : iconButtonProps.label}>
      <IconButton
        {...iconButtonProps}
        className={cx(cl['bk-dialog__action--icon'], iconButtonProps.className)}
      />
    </TooltipProvider>
  );
};

