          icon={icon}
          decoration={iconDecoration !== 'highlight' ? undefined : { type: 'background-circle' }}
          className={cx(
            cl['bk-list-box__item__icon'],
            { [cl['bk-list-box__item__icon--highlight']]: iconDecoration === 'highlight' },
