@use '../context/theming.scss' as theming;

@mixin text-defaults {
  font-family: var(--bk-font-family-body);
  line-height: 1.6; // https://css-tricks.com/how-to-tame-line-height-in-css
  //color: ...; // Handled by theming.scss
